import * as React from "react";
import { fireEvent, render, screen } from "@testing-library/react";
import { Info as InfoIcon } from "@airbus/icons/react";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import ConsoleSpy from "../../lib/tests/ConsoleSpy";
import IconButton from "../IconButton";
import Input from "../Input";
import Tooltip from "../Tooltip";
import * as stories from "./FormControl.stories";
import { FormControl } from ".";

const { Basic } = composeStories(stories) as any;

describe("FormControl component", () => {
  let consoleSpy = ConsoleSpy();

  it("pass A11Y", async () => {
    const { container } = render(<Basic />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("should pass valid/invalid states to wrapped controls", () => {
    render(
      <FormControl label="LABEL" error>
        <Input data-testid="input" />
      </FormControl>
    );
    expect(screen.getByTestId("input")).toHaveClass("ds-input--invalid");
  });

  it("passes through props", () => {
    render(
      <FormControl data-testid="formcontrol">
        <Input />
      </FormControl>
    );
    expect(screen.getByTestId("formcontrol")).toBeTruthy();
  });

  it("supports tooltip in labelAdornment", () => {
    render(
      <FormControl
        label="Label"
        labelAdornment={
          <Tooltip placement="top" label="Lorem Ipsum">
            <IconButton size="xsmall" variant="ghost">
              <InfoIcon />
            </IconButton>
          </Tooltip>
        }
      >
        <Input />
      </FormControl>
    );
    fireEvent.mouseEnter(screen.getByRole("button"));
    expect(consoleSpy.warn).toHaveBeenCalledTimes(0);
    expect(consoleSpy.error).toHaveBeenCalledTimes(0);
  });
});
